const hash=text=>createHash('sha256').update(text).digest('hex');
let vectors=[];const retain=(kind,value)=>{vectors.push({kind,value});return value;};
const test=(name,run)=>testCase(name,{timeout:60_000},async()=>{vectors=[];try{await run();}finally{if(process.env.ROUTER_BORROWED_JSON_LET_ELSE_VECTOR_DIR){const directory=process.env.ROUTER_BORROWED_JSON_LET_ELSE_VECTOR_DIR;mkdirSync(directory,{recursive:true});writeFileSync(join(directory,Buffer.from(name).toString('hex')+'.json'),JSON.stringify({name,vectors},(_key,value)=>typeof value==='bigint'?{$integer:String(value)}:value)+'\n');}}});
const dependencies=()=>loadJsonMacroSourceProof({manifest:readFileSync(new URL('../../../rust/Cargo.toml',import.meta.url),'utf8'),lock:readFileSync(repositorySourceURL("Cargo.lock",new URL('../../../',import.meta.url)),'utf8')});
const core=source=>({'src/lib.rs':'pub mod translation_core;\n'+source,'src/translation_core.rs':ROUTER_FORMATTING_FACADE_SOURCE,'src/translation_core/primitives.rs':ROUTER_CORE_PRIMITIVES_SOURCE,'src/translation_core/ranges.rs':ROUTER_CORE_RANGES_SOURCE});
function project(input,{json=true}={}){if(typeof input==='string')input={'src/lib.rs':input};retain('complete-source-input',input);return retain('complete-project-result',translateProject({entry:'src/lib.rs',paths:Object.keys(input),readSource:path=>input[path],compilationProfile:PRODUCTION_PROFILE,...(json?{jsonMacroDependencies:dependencies()}:{})}));}
const admitted=(result,name)=>result.meta.executable.some(row=>row.name===name);
const nodes=(value,predicate,result=[])=>{if(value&&typeof value==='object'){if(predicate(value))result.push(value);for(const [key,child]of Object.entries(value))if(!['type','contract','sourceLifetimeProof','sharedCopy'].includes(key)){if(Array.isArray(child))for(const row of child)nodes(row,predicate,result);else nodes(child,predicate,result);}}return result;};
async function targets(result,verify){const wire=JSON.stringify(result.meta.checkedSemanticProgram);assert.equal(serializeProgram(parseProgram(wire)),wire);retain('complete-targets',{wire,javascript:result.javascript,typescript:result.typescript});await verifyTypedTargets(result,verify,{childTimeoutMs:20_000});}
const none=Object.freeze({$:'None'}),some=value=>Object.freeze({$:'Some',field0:value}),ok=value=>({$:'Ok',field0:value});
function json(value){const parsed=serde_json_from_str(JSON.stringify(value));assert.equal(parsed.$,'Ok');return parsed.field0;}
function requireFunctions(result,names){for(const name of names)assert.equal(admitted(result,name),true,JSON.stringify({name,refused:result.meta.refused}));}
function refuse(source){const result=project(source);assert.equal(admitted(result,'bad'),false,source);assert.ok(result.meta.refused.some(row=>row.name==='bad'),JSON.stringify(result.meta.refused));return result;}

test('shared canonical JSON Some binding preserves the selected reference and both divergent branches',async()=>{
  const source='use serde_json::Value; pub fn pick(body:&Value)->Option<&Value>{let Some(value)=body.get("x") else{return None;};Some(value)} pub fn null(body:&Value)->bool{let Some(value)=body.get("x") else{return false;};value.is_null()}',result=project(source);requireFunctions(result,['pick','null']);
  const controls=nodes(result.meta.checkedSemanticProgram.program.items,node=>node.patternControl?.sharedCopy);assert.equal(controls.length,2);
  for(const node of controls){const proof=node.patternControl.sharedCopy;assert.equal(proof.profile,'canonical-option-shared-json-let-else-v1');assert.equal(proof.copy.owner,'core::option::Option');assert.equal(proof.copy.referenceDepth,1);assert.equal(proof.copy.referenceSource.pointeeCopyRequired,false);assert.equal(proof.pointeeMoveAuthority,false);assert.equal(proof.pointeeDropAuthority,false);assert.equal(proof.lifetimeAuthority,false);assert.equal(nodes(node.body,node=>node.k==='routerPatternImmutable'&&node.borrowedAggregate).length>0,true);}
  await targets(result,api=>{assert.deepEqual(api.pick(json({})),none);for(const value of [null,true,'Ω😀',[],{nested:'x'}]){const body=json({x:value}),selected=body.field0.entries[0].value;assert.strictEqual(api.pick(body).field0,selected);assert.equal(api.null(body),value===null);}assert.equal(api.null(json({})),false);});
});

test('JSON Map and borrowed str projections retain input lifetimes and shadowing',async()=>{
  const source='use serde_json::Value; pub fn text(body:&Value)->Option<&str>{let Some(body)=body.get("metadata") else{return None;};let Some(body)=body.as_object() else{return None;};let Some(body)=body.get("user_id") else{return None;};let Some(body)=body.as_str() else{return None;};Some(body)} pub fn nested(body:&Value)->Result<Option<&str>,String>{let Some(value)=body.get("x") else{return Ok(None);};let Some(value)=value.as_str() else{return Err("not text".into());};Ok(Some(value))} pub fn carried(value:Option<&str>,empty:bool)->Result<Option<&str>,String>{if empty{return Ok(None);};Ok(value)} pub fn deeper(value:Option<Option<&str>>,empty:bool)->Result<Option<Option<&str>>,String>{if empty{return Ok(Some(None));};Ok(value)} pub fn absent()->Result<Option<&\'static str>,String>{Ok(None)} pub fn failed()->Result<Option<&\'static str>,String>{Err("missing".into())}',result=project(source);requireFunctions(result,['text','nested','carried','deeper','absent','failed']);
  const controls=nodes(result.meta.checkedSemanticProgram.program.items,node=>node.patternControl?.sharedCopy);assert.equal(controls.length,4);assert.equal(controls.some(node=>node.patternControl.sharedCopy.pointee.name==='serde_json.Map_String_Value'),true);
  await targets(result,api=>{for(const value of [{},{metadata:null},{metadata:[]},{metadata:{}},{metadata:{user_id:7}}])assert.deepEqual(api.text(json(value)),none);for(const value of ['','Ω😀','e\u0301'])assert.deepEqual(api.text(json({metadata:{user_id:value}})),some(value));
    assert.deepEqual(api.nested(json({})),ok(none));assert.deepEqual(api.nested(json({x:7})),{$:'Err',field0:'not text'});for(const value of ['','Ω😀','e\u0301'])assert.deepEqual(api.nested(json({x:value})),ok(some(value)));
    for(const value of [none,some('Ω😀')]){assert.deepEqual(api.carried(value,true),ok(none));assert.deepEqual(api.carried(value,false),ok(value));}for(const value of [none,some(none),some(some('Ω😀'))]){assert.deepEqual(api.deeper(value,true),ok(some(none)));assert.deepEqual(api.deeper(value,false),ok(value));}assert.deepEqual(api.absent(),ok(none));assert.deepEqual(api.failed(),{$:'Err',field0:'missing'});
  });
});

test('borrowed subjects are evaluated once and failure returns stay lazy',async()=>{
  const source='use serde_json::Value; fn failure()->bool{panic!("absent")} pub fn lazy(body:&Value)->bool{let Some(value)=body.get("x") else{return failure();};value.is_null()} pub fn key(body:&Value,key:&str)->bool{let Some(value)=body.get(key) else{return false;};value.is_null()}',result=project(source);requireFunctions(result,['failure','lazy','key']);
  const lazy=result.meta.checkedSemanticProgram.program.items.find(row=>row.fullName==='lazy'||row.name==='lazy');assert.ok(lazy);assert.equal(nodes(lazy.body,node=>node.k==='routerHostCall'&&node.id==='serde_json_value_get_string').length,1);
  await targets(result,api=>{assert.equal(api.lazy(json({x:null})),true);assert.equal(api.lazy(json({x:false})),false);assert.throws(()=>api.lazy(json({})),/absent/);assert.equal(api.key(json({a:null}),'a'),true);assert.equal(api.key(json({a:null}),'b'),false);});
});

test('owned mutable moving nested and unknown aggregate payloads remain refused',()=>{
  const cases=[
    'use serde_json::Value; pub fn bad(value:Option<Value>)->bool{let Some(value)=value else{return false;};true}',
    'use serde_json::Value; pub fn bad(value:Option<&mut Value>)->bool{let Some(value)=value else{return false;};true}',
    'use serde_json::Value; pub fn bad(value:Option<&&Value>)->bool{let Some(value)=value else{return false;};true}',
    'struct Other{value:u8} pub fn bad(value:Option<&Other>)->bool{let Some(value)=value else{return false;};true}',
    'pub fn bad(value:Option<Vec<u8>>)->bool{let Some(value)=value else{return false;};true}',
    'pub fn bad(value:Option<Option<u8>>)->bool{let Some(value)=value else{return false;};true}',
    'use serde_json::Value; pub fn bad(value:Option<&Value>)->bool{let Some(mut value)=value else{return false;};true}',
    'use serde_json::Value; pub fn bad(value:Option<&Value>)->bool{let Some(ref value)=value else{return false;};true}',
    'use serde_json::Value; enum Fake{Some(Value),None} pub fn bad(value:Fake)->bool{let Fake::Some(value)=value else{return false;};true}',
    'use serde_json::Value; pub fn bad(body:&Value)->bool{let Some(value)=body.get("x") else{false};true}',
  ];for(const source of cases)refuse(source);retain('complete-negative-sources',cases);
});

test('escaping borrows counterfeit source layouts and cross-analysis syntax cannot gain authority',()=>{
  for(const source of [
    'use serde_json::Value; pub fn bad(body:&Value)->Option<&\'static Value>{let Some(value)=body.get("x") else{return None;};Some(value)}',
    'use serde_json::Value; pub fn bad(body:&Value,other:&Value)->Option<&Value>{let Some(value)=body.get("x") else{return None;};Some(value)}',
    "pub fn bad(value:&str)->Result<Option<&'static str>,String>{Ok(Some(value))}",
    "pub fn bad(value:&str,empty:bool)->Result<Option<&'static str>,String>{if empty{Ok(None)}else{Ok(Some(value))}}",
    "pub fn bad(value:Option<&str>)->Result<Option<&'static str>,String>{Ok(value)}",
    "use serde_json::Value; pub fn bad(body:&Value)->Result<Option<&'static str>,String>{let Some(value)=body.get(\"x\") else{return Ok(None);};let Some(value)=value.as_str() else{return Err(\"not text\".into());};Ok(Some(value))}",
    'mod serde_json{pub enum Value{Null}} pub fn bad(body:Option<&serde_json::Value>)->bool{let Some(value)=body else{return false;};true}',
    'enum Option<T>{Some(T),None} use serde_json::Value; pub fn bad(body:Option<&Value>)->bool{let Some(value)=body else{return false;};true}',
  ])refuse(source);
  // Equal portable layouts must retain each written argument's own lifetime
  // and span, independently of which declaration first filled the layout table.
  const declarations=[
    {name:'elided',kind:'elided',written:'&str',depth:1,source:'pub fn elided(value:Option<&str>)->Result<Option<&str>,String>{Ok(value)}'},
    {name:'fixed',kind:'static',written:"&'static str",depth:1,source:"pub fn fixed(value:Option<&'static str>)->Result<Option<&'static str>,String>{Ok(value)}"},
    {name:'named',kind:'named:a',written:"&'a str",depth:1,source:"pub fn named<'a>(value:Option<&'a str>)->Result<Option<&'a str>,String>{Ok(value)}"},
    {name:'deeper',kind:'elided',written:'&str',depth:2,source:'pub fn deeper(value:Option<Option<&str>>)->Result<Option<Option<&str>>,String>{Ok(value)}'},
  ];
  const argument=(type,depth)=>{for(let at=0;at<depth;at++)type=type.rustStandardGeneric.arguments[0];return type;};
  for(const ordered of [declarations,[...declarations].reverse()]){
    const source=ordered.map(row=>row.source).join(' ')+' fn main(){}',surface=parseRust(source),observed=[];
    for(const row of ordered){
      const entry=surface.items.find(item=>item.k==='fn'&&item.name===row.name);assert.ok(entry);
      const input=argument(entry.params[0].type,row.depth),output=argument(entry.ret,row.depth+1),start=source.indexOf(row.source),first=source.indexOf(row.written,start),second=source.indexOf(row.written,first+row.written.length);
      for(const [type,offset]of [[input,first],[output,second]]){const lifetime=type.rustBorrowLifetime;assert.equal(lifetime.kind,row.kind);assert.deepEqual(lifetime.span,{start:offset,end:offset+row.written.length});assert.equal(source.slice(lifetime.span.start,lifetime.span.end),row.written);}
      assert.notStrictEqual(input,output);observed.push({name:row.name,input,output});
    }
    retain('complete-per-use-generic-lifetime-syntax',{source,surface,observed});
  }
  for(const prefix of ['',"fn seed(value:Option<&'static str>)->Option<&'static str>{value} ",'fn seed(value:Option<&str>)->Option<&str>{value} '])for(const body of [
    "pub fn bad(value:Option<&str>)->Option<&'static str>{value}",
    "pub fn bad(value:Result<Option<&str>,String>)->Result<Option<&'static str>,String>{value}",
    "fn needs(value:Option<&'static str>)->u8{1} pub fn bad(value:Option<&str>)->u8{needs(value)}",
  ])refuse(prefix+body);
  // Original parser association is object-specific, not a hash or a copied
  // proof. Swapping a different parse's node after capture invalidates it.
  const source='pub fn selected(body:&serde_json::Value)->bool{let Some(value)=body.get("x") else{return false;};value.is_null()} fn main(){}',left=parseRust(source),right=parseRust(source),leftFn=left.items.find(row=>row.k==='fn'&&row.name==='selected'),rightFn=right.items.find(row=>row.k==='fn'&&row.name==='selected');assert.ok(leftFn);assert.ok(rightFn);
  const leftCall=nodes(leftFn.body,node=>node.k==='routerLetElse')[0],rightCall=nodes(rightFn.body,node=>node.k==='routerLetElse')[0];assert.ok(leftCall);assert.ok(rightCall);assert.strictEqual(originalParsedSyntaxNode(leftFn,leftCall).actual,leftCall);assert.equal(originalParsedSyntaxNode(leftFn,rightCall),null);assert.equal(originalParsedSyntaxNode(structuredClone(leftFn),leftCall),null);const clone=structuredClone(left);assert.throws(()=>checkProgram(clone));
  const previous=leftFn.body;try{leftFn.body=rightFn.body;assert.throws(()=>checkProgram(left));}finally{leftFn.body=previous;}retain('complete-source-association-controls',{source,left,right,cloned:structuredClone(leftFn)});
  const checker=new HostChecker('Rust',[]),checked=checker.program(left);assert.equal(checked.declarations.has('selected'),true);const env=new Map(checked.declarations.get('selected').params.map(param=>[param.name,param.type])),controls=[];
  for(const name of ['sourceStandardFieldCopy','hostType','expectedOwnership'])for(const mode of ['method','getter']){let calls=0;const saved=Object.getOwnPropertyDescriptor(checker,name),hook=()=>{calls++;throw Error('must not invoke '+name);};Object.defineProperty(checker,name,mode==='method'?{value:hook,configurable:true}:{get:hook,configurable:true});let message;try{assert.throws(()=>checker.expr(leftCall,env,[],BOOL),error=>{message=error.message;return /Original parser\/cursor/.test(message);});}finally{if(saved)Object.defineProperty(checker,name,saved);else delete checker[name];}assert.equal(calls,0);controls.push({name,mode,calls,message});}
  const scalar=checkScalarPattern(parseScalarPattern('pub fn scalar(value:Option<u8>)->u8{let Some(value)=value else{return 7;};value} fn main(){}'));assert.equal(scalar.declarations.get('scalar').body.patternControl.kind,'let-else');assert.equal(scalar.declarations.get('scalar').body.patternControl.sharedCopy,undefined);retain('standalone-scalar-path',scalar);
  let fakeCalls=0;const fake=Object.defineProperty({},'contextEnvironment',{get(){fakeCalls++;throw Error('fake checker callback');}});captureOriginalStandardCalls(fake,left);assert.throws(()=>HostChecker.prototype.expr.call(fake,leftCall,env,[],BOOL),/Original parser\/cursor/);assert.equal(fakeCalls,0);retain('complete-live-checker-override-refusals',{controls,fakeCalls,restored:checker.expr(leftCall,env,[],BOOL)});
});

