test('complete unchanged safety module gains anthropic identifier behavior with sealed Cargo JSON context',async()=>{
  assert.equal(hash(SAFETY_SOURCE),SAFETY_SHA256);const input={...core('pub mod safety_identifier;'),'src/safety_identifier.rs':SAFETY_SOURCE},without=project(input,{json:false}),result=project(input);retain('complete-missing-and-genuine-dependency-results',{without,result});
  for(const name of ['validate_openai_value','validate_openai_user_value'])assert.equal(admitted(without,'safety_identifier.'+name),false,name+' still requires its actual JSON source context');
  const names=['validate_openai','validate_openai_user','validate_openai_value','validate_openai_user_value','anthropic_user_id'].map(name=>'safety_identifier.'+name);requireFunctions(result,names);
  const physical=readFileSync(new URL('../../../rust/src/safety_identifier.rs',import.meta.url),'utf8'),current=project({...core('pub mod safety_identifier;'),'src/safety_identifier.rs':physical});retain('complete-current-physical-safety',{source:physical,sha256:hash(physical),current});requireFunctions(current,names);
  const item=sourceItems(SAFETY_SOURCE).find(row=>row.term==='fn'&&row.name==='anthropic_user_id');assert.ok(item);assert.deepEqual(result.meta.executable.find(row=>row.name==='safety_identifier.anthropic_user_id').span,{start:item.start,end:item.end});
  const verify=api=>{
    const run=(name,value)=>retain('actual-safety-outcome',{name,value,result:api['safety_identifier.'+name](value)}).result,long='😀'.repeat(65);
    for(const name of ['validate_openai','validate_openai_user']){assert.deepEqual(run(name,none),ok(null));for(const value of ['', 'a'.repeat(64),'😀'.repeat(64),'e\u0301'.repeat(32)])assert.deepEqual(run(name,some(value)),ok(null));assert.equal(run(name,some(long)).$,'Err');}
    for(const name of ['validate_openai_value','validate_openai_user_value']){assert.deepEqual(run(name,none),ok(null));assert.deepEqual(run(name,some(json(null))),ok(null));assert.equal(run(name,some(json(7))).$,'Err');assert.equal(run(name,some(json(long))).$,'Err');}
    for(const [body,expected]of [[{},ok(none)],[{metadata:{}},ok(none)],[{metadata:{user_id:''}},ok(some(''))],[{metadata:{user_id:'Ω😀'}},ok(some('Ω😀'))],[{metadata:7},{$:'Err',field0:'metadata must be an object'}],[{metadata:{user_id:false}},{$:'Err',field0:'metadata.user_id must be a string'}]])assert.deepEqual(run('anthropic_user_id',json(body)),expected);
    assert.match(run('anthropic_user_id',json({metadata:{user_id:long}})).field0,/at most 64 characters/);
  };await targets(result,verify);if(physical!==SAFETY_SOURCE)await targets(current,verify);
});

test('two other complete original callers retain checked outcomes or explicit follow-on refusals',async()=>{
  const workloads=[{source:TOOLS_SOURCE,hash:TOOLS_SHA256,name:'anthropic_parallel_tool_calls',file:'src/bridge_request_tools.rs'},{source:USAGE_SOURCE,hash:USAGE_SHA256,name:'recognizable_anthropic_limit',file:'src/subscription_usage_normalize.rs'}];
  for(const row of workloads){assert.equal(hash(row.source),row.hash);const item=sourceItems(row.source).find(item=>item.term==='fn'&&item.name===row.name);assert.ok(item);const declaration=row.source.slice(item.start,item.end),input={'src/lib.rs':'mod original;','src/original.rs':'use serde_json::Value;\n'+declaration},result=project(input);retain('complete-other-original-function',{...row,span:{start:item.start,end:item.end},declaration,sha256:hash(declaration),input,result});
    // These actual full bodies include independent Option callback/primitive
    // obligations. A remaining refusal is retained, never counted as a gain.
    if(!admitted(result,'original.'+row.name)){const refusal=result.meta.refused.find(item=>item.name==='original.'+row.name);assert.ok(refusal);assert.doesNotMatch(refusal.message,/let-else aggregate binding/);continue;}
    await targets(result,api=>{const fn=api['original.'+row.name];if(row.name==='anthropic_parallel_tool_calls'){for(const [body,expected]of [[{},ok(none)],[{tool_choice:null},ok(none)],[{tool_choice:{}},ok(none)],[{tool_choice:{disable_parallel_tool_use:true}},ok(some(false))],[{tool_choice:{disable_parallel_tool_use:false}},ok(some(true))],[{tool_choice:{disable_parallel_tool_use:'no'}},{$:'Err',field0:'tool_choice.disable_parallel_tool_use must be a boolean'}]])assert.deepEqual(fn(json(body)),expected);}else{for(const [body,expected]of [[null,false],[{},false],[{kind:'x'},false],[{kind:'x',percent:1},true],[{group:'x',resets_at:'now'},true],[{scope:{model:{display_name:'x'}},percent:1},true],[{kind:0,percent:1},false]])assert.equal(fn(json(body)),expected);}});
  }
});

test('borrowed runtime rejects proxies getters mutable views and invalid JSON without reading hooks',async()=>{
  const result=project('use serde_json::Value; pub fn pick(body:&Value)->Option<&Value>{let Some(value)=body.get("x") else{return None;};Some(value)}');requireFunctions(result,['pick']);
  await targets(result,api=>{const body=json({x:'Ω😀'});let calls=0;const proxy=new Proxy(body,{get(){calls++;throw Error('get');},ownKeys(){calls++;throw Error('keys');},getOwnPropertyDescriptor(){calls++;throw Error('descriptor');},getPrototypeOf(){calls++;throw Error('prototype');}}),accessor=Object.freeze(Object.defineProperty({},'$',{enumerable:true,get(){calls++;return 'Object';}}));for(const value of [proxy,accessor,{$:'Object',field0:body.field0},Object.freeze({$:'Other'}),Object.freeze({$:'Object',field0:Object.freeze({$:'Map',entries:Object.freeze([Object.freeze({$:'MapEntry',key:'x',value:Object.freeze({$:'Other'})})])})})])assert.throws(()=>api.pick(value),TypeError);assert.equal(calls,0);assert.strictEqual(api.pick(body).field0,body.field0.entries[0].value);});
});
